export const getListSupplyChainEventsUrl = (params?: ListSupplyChainEventsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/supply-chain/events?${stringifiedParams}` : `/api/supply-chain/events`
}

